function shippingCost(kind: string, weightKg: number): number {
	if (kind === "express") {
		return 20 + weightKg * 4;
	}
	if (kind === "economy") {
		return 5 + weightKg * 1.5;
	}
	if (kind === "pickup") {
		return 0;
	}
	throw new Error(`unknown kind: ${kind}`);
}

