class Order {
	private status = "pending";

	pay(): void {
		if (this.status === "pending") this.status = "paid";
		else throw new Error("cannot pay");
	}

	ship(): void {
		if (this.status === "paid") this.status = "shipped";
		else throw new Error("cannot ship");
	}

	cancel(): void {
		if (this.status === "pending" || this.status === "paid") this.status = "cancelled";
		else throw new Error("cannot cancel");
	}
}

