class Subject {
	private listeners: Array<(event: string) => void> = [];

	subscribe(listener: (event: string) => void): void {
		this.listeners.push(listener);
	}

	publish(event: string): void {
		for (const listener of this.listeners) {
			listener(event);
		}
	}
}

